public interface Extensible {
    <T> T getExtension(Class<T> type);           // null == absent
}
public final class Document implements Extensible {
    private final Map<Class<?>, Object> exts = new HashMap<>();
    public <T> void addExtension(Class<T> type, T ext) { exts.put(type, ext); }
    public <T> T getExtension(Class<T> type) { return type.cast(exts.get(type)); }
}
